arguments.command:
set -e; rm -rf /tmp/t2; mkdir -p /tmp/t2/src /tmp/t2/data; cp /app/src/program.cbl /tmp/t2/src/; cp /tmp/data_orig/*.DAT /tmp/t2/data/;
printf 'U001U002B0010000000200' > /tmp/t2/src/INPUT.DAT   # full 22 bytes amount=0000000200=200
cd /tmp/t2; /tmp/prog >/dev/null; 
echo "=== ACCOUNTS ==="; od -An -c data/ACCOUNTS.DAT | head
echo "=== TRANS tail ==="; od -An -c data/TRANSACTIONS.DAT | tail -3

